import netCDF4

def main():
    path = '/benchmark/datasets/temperature_statistic/E1_north_america.nc'
    ds = netCDF4.Dataset(path)
    print('Variables:', list(ds.variables.keys()))
    for var in ds.variables:
        print(f'{var}: shape={ds.variables[var].shape}, dtype={ds.variables[var].dtype}')
    if 'time' in ds.variables:
        print('Time variable shape:', ds.variables['time'].shape)
        print('Time variable content:', ds.variables['time'][:])
    ds.close()

if __name__ == '__main__':
    main()

